'use strict';
const selectedScents=new Set();
document.querySelectorAll('[data-scent]').forEach(b=>b.addEventListener('click',()=>{const n=b.dataset.scent;if(selectedScents.has(n)){selectedScents.delete(n);}else{selectedScents.add(n);}b.setAttribute('aria-pressed',String(selectedScents.has(n)));b.innerHTML=selectedScents.has(n)?`ĐÃ CHỌN ${n} <span>✓</span>`:`CHỌN HƯƠNG ${n.replace('SR ','')} <span>＋</span>`;const note=document.querySelector('#note');const rest=note.value.replace(/^Mùi đã chọn: [^\n]*(\n|$)/,'');note.value=(selectedScents.size?'Mùi đã chọn: '+[...selectedScents].join(', ')+'\n':'')+rest;document.querySelector('#scent-status').textContent=selectedScents.size?'Đã thêm vào lời nhắn: '+[...selectedScents].join(', '):'Bạn có thể chọn nhiều mùi cho combo.';}));
